import java.util.ArrayDeque;
import java.util.Deque;

public class MinStack {
    // 用 ArrayDeque 代替 Stack（Stack 继承自 Vector，方法带 synchronized，性能略差）
    private final Deque<Integer> data;
    private final Deque<Integer> min;

    public MinStack() {
        data = new ArrayDeque<>();
        min = new ArrayDeque<>();
    }

    public void push(int val) {
        data.push(val);
        // 关键：用 <= 而非 <，保证重复最小值时辅助栈也同步压入
        if (min.isEmpty() || val <= min.peek()) {
            min.push(val);
        } else {
            min.push(min.peek());
        }
    }

    public void pop() {
        data.pop();
        min.pop();
    }

    public int top() {
        return data.peek();
    }

    public int getMin() {
        return min.peek();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

public class MinStackDiff {
    private final Deque<Long> stack; // 存差值，必须用 long 防溢出
    private long min;

    public MinStackDiff() {
        stack = new ArrayDeque<>();
    }

    public void push(int val) {
        if (stack.isEmpty()) {
            min = val;
            stack.push(0L);
        } else {
            long diff = (long) val - min;
            stack.push(diff);
            if (diff < 0) {
                // val 比当前 min 更小，更新 min
                min = val;
            }
        }
    }

    public void pop() {
        long diff = stack.pop();
        if (diff < 0) {
            // 弹出时 diff<0 说明这个元素曾更新过 min，需要恢复旧 min
            // 旧 min = 当前 min - diff（diff 是负数，所以是加）
            min = min - diff;
        }
        // diff >= 0 时 min 不变
    }

    public int top() {
        long diff = stack.peek();
        if (diff < 0) {
            return (int) min; // 当前栈顶就是 min
        }
        return (int) (min + diff);
    }

    public int getMin() {
        return (int) min;
    }
}
